import React, { useMemo } from 'react';
import { useState, useEffect } from 'react'
import { Upload, Heart, Moon, Sun, Search } from 'lucide-react'
import { LazyLoadImage } from 'react-lazy-load-image-component';

const server_ip = "https://api.rev-we.ordinall.me"

interface SearchResult {
  url: string
  tags: string[]
  score: number
  fileid: string
  title: string
}

interface SearchResponse {
  processing_time: number
  total_documents: number
  results: SearchResult[]
}

function SteamLogo({ width = 30, height = 30, className = '' }) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width={width} height={height} fill="currentColor" className={className} viewBox="0 0 16 16">
      <path d="M.329 10.333A8.01 8.01 0 0 0 7.99 16C12.414 16 16 12.418 16 8s-3.586-8-8.009-8A8.006 8.006 0 0 0 0 7.468l.003.006 4.304 1.769A2.2 2.2 0 0 1 5.62 8.88l1.96-2.844-.001-.04a3.046 3.046 0 0 1 3.042-3.043 3.046 3.046 0 0 1 3.042 3.043 3.047 3.047 0 0 1-3.111 3.044l-2.804 2a2.223 2.223 0 0 1-3.075 2.11 2.22 2.22 0 0 1-1.312-1.568L.33 10.333Z"/>
      <path d="M4.868 12.683a1.715 1.715 0 0 0 1.318-3.165 1.7 1.7 0 0 0-1.263-.02l1.023.424a1.261 1.261 0 1 1-.97 2.33l-.99-.41a1.7 1.7 0 0 0 .882.84Zm3.726-6.687a2.03 2.03 0 0 0 2.027 2.029 2.03 2.03 0 0 0 2.027-2.029 2.03 2.03 0 0 0-2.027-2.027 2.03 2.03 0 0 0-2.027 2.027m2.03-1.527a1.524 1.524 0 1 1-.002 3.048 1.524 1.524 0 0 1 .002-3.048"/>
    </svg>
  )
}

function SearchThisButton({ onClick, enabled }: { onClick: () => void, enabled?: boolean }) {
  const [disabled, setDisabled] = useState(false);

  useEffect(() => {
    if (enabled === undefined) return;
    if (disabled === true && enabled === true) {
      setDisabled(false);
    }
  }, [enabled, disabled]);

  return (
    <button
      className="bg-white text-xs dark:bg-gray-800 dark:hover:bg-gray-700 hover:bg-gray-100 text-gray border border-gray-400 py-1 px-2 rounded-lg shadow inline-flex items-center space-x-1"
      onClick={(e) => {

        setDisabled(true);
        onClick();
        e.stopPropagation();
      }}
      disabled={disabled}
    >
      {disabled ? (
        <svg aria-hidden="true" className="inline w-5 h-5 text-blue-500 animate-spin fill-white" viewBox="0 0 100 101" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M100 50.5908C100 78.2051 77.6142 100.591 50 100.591C22.3858 100.591 0 78.2051 0 50.5908C0 22.9766 22.3858 0.59082 50 0.59082C77.6142 0.59082 100 22.9766 100 50.5908ZM9.08144 50.5908C9.08144 73.1895 27.4013 91.5094 50 91.5094C72.5987 91.5094 90.9186 73.1895 90.9186 50.5908C90.9186 27.9921 72.5987 9.67226 50 9.67226C27.4013 9.67226 9.08144 27.9921 9.08144 50.5908Z" fill="currentColor"/>
          <path d="M93.9676 39.0409C96.393 38.4038 97.8624 35.9116 97.0079 33.5539C95.2932 28.8227 92.871 24.3692 89.8167 20.348C85.8452 15.1192 80.8826 10.7238 75.2124 7.41289C69.5422 4.10194 63.2754 1.94025 56.7698 1.05124C51.7666 0.367541 46.6976 0.446843 41.7345 1.27873C39.2613 1.69328 37.813 4.19778 38.4501 6.62326C39.0873 9.04874 41.5694 10.4717 44.0505 10.1071C47.8511 9.54855 51.7191 9.52689 55.5402 10.0491C60.8642 10.7766 65.9928 12.5457 70.6331 15.2552C75.2735 17.9648 79.3347 21.5619 82.5849 25.841C84.9175 28.9121 86.7997 32.2913 88.1811 35.8758C89.083 38.2158 91.5421 39.6781 93.9676 39.0409Z" fill="currentFill"/>
        </svg>
      ) : (
        <Search className="h-5 w-5" />
      )}
      <span>
        {disabled ? 'Searching' : 'Search this'}
      </span>
    </button>
  )
}

export default function AppOld() {
  const nsfwInitail = useMemo(() => {
    const nsfw = localStorage.getItem('removeNsfw');
    if (nsfw === '1' || nsfw === null) {
      return true;
    }
  }, []);
  const [inputValue, setInputValue] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [removeNsfw, setRemoveNsfw] = useState(nsfwInitail);
  const [isHealthy, setIsHealthy] = useState(false);
  const [checkingHealth, setCheckingHealth] = useState(true);
  const [searching, setSearching] = useState(false);
  const [resultEmpty, setResultEmpty] = useState(false);
  const [searchResponse, setSearchResponse] = useState<SearchResponse | null>(null);
  const [searchError, setSearchError] = useState(false);
  const [searchErrorText, setSearchErrorText] = useState('');
  const [searches, setSearches] = useState<Number | null>(null);
  const [datasetUpdated, setDatasetUpdated] = useState<Date | null>(null);
  const [validationError, setValidationError] = useState<number | null>(null);
  const [darkMode, setDarkMode] = useState(() => localStorage.getItem('theme') === 'dark');


  const checkHealth = async () => {
    try {
      setCheckingHealth(true);
      const response = await fetch(server_ip + '/health');
      const data = await response.json();
      if (data.status === "Healthy") {
        setIsHealthy(true);
        if (data.searches) {
          setSearches(data.searches);
        }
        if (data.datasetUpdated) {
          setDatasetUpdated(new Date(data.datasetUpdated));
        }
      } else {
        setIsHealthy(false);
      }
    } catch (error) {
      console.error('Error checking health:', error);
      setIsHealthy(false);
    }
    setCheckingHealth(false);
  }

  useEffect(() => {
    checkHealth();
  }, [])

  useEffect(() => {
    document.documentElement.classList.toggle('dark', darkMode);
    localStorage.setItem('theme', darkMode ? 'dark' : 'light');
  }, [darkMode]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(e.target.value);
    if (inputValue !== "Image pasted From Clipboard...") {
      setFile(null);
    }
    setValidationError(null);
  }

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setInputValue(e.target.files[0].name);
      setValidationError(null);
    }
  }

  const handlePasteCapture = (e: React.ClipboardEvent<HTMLInputElement>) => {
    const files = e.clipboardData.files;
    if (files.length > 0) {
      if (files[0].type.indexOf('image') !== -1) {
        setFile(files[0]);
        setInputValue("Image pasted From Clipboard...");
        setValidationError(null);
      }
    } else {
      const text = e.clipboardData.getData('text');
      if (text) {
        setFile(null);
        setValidationError(null);
      }
    }
  }

  const handleOnFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    setValidationError(null);
    e.target.select();
  }

  const searchImage = async (input?: string) => {
    const formData = new FormData();
    if (file && !input) {
      formData.append('file', file);
    } else {
      if (!inputValue) {
        setValidationError(1);
        console.log('Validation error');
        return;
      }
      if (input) {
        formData.append('image_url', input);
      } else {
        formData.append('image_url', inputValue);
      }
    }
    formData.append('remove_nsfw', removeNsfw ? '1' : '0');
    if (input) {
      setInputValue(input);
      setFile(null);
    }
    try {
      setSearching(true);
      const response = await fetch(server_ip + '/search', {
        method: 'POST',
        body: formData,
      });
      if (response.status === 400) {
        const data = await response.json();
        setSearchErrorText(data.detail);
        setSearchError(true);
        checkHealth();
      } else {
        const data: SearchResponse = await response.json();
        if (data.results.length === 0) {
          setResultEmpty(true);
        } else {
          setResultEmpty(false);
        }
        setSearchResponse(data);
        setSearchError(false);
        setSearchErrorText('');
      
        if (input) {
          window.history.pushState({searchResponse: data, inputValue: input, file: null}, '');
        } else {
          window.history.pushState({searchResponse: data, inputValue: inputValue, file: file}, '');
        }
      }
    } catch (error) {
      console.error('Error searching image:', error);
      setSearchError(true);
      setSearchErrorText('');
      checkHealth();
    }
    setSearching(false);
  }

  useEffect(() => {
    const handlePopState = (e: PopStateEvent) => {
      if (e.state) {
        setSearchResponse(e.state.searchResponse || null);
        setInputValue(e.state.inputValue || '');
        setFile(e.state.file || null);
      } else {
        setSearchResponse(null);
        setInputValue('');
        setFile(null);
      }
    }

    window.addEventListener('popstate', handlePopState);

    return () => {
      window.removeEventListener('popstate', handlePopState);
    }
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    searchImage();
  }

  return (
    <div className="min-h-screen dark:bg-gradient-to-br dark:from-gray-900 dark:to-gray-800 dark:text-gray-200 bg-gradient-to-br from-gray-100 to-gray-200 flex flex-col items-center justify-center p-4 transition-all duration-300">
      <header className="w-full max-w-6xl text-center text-gray-500 dark:text-gray-300 flex items-center justify-between transition-all duration-300">
        <span className="flex items-center space-x-1">
          <span>Made with</span>
          <Heart className="h-4 w-4 text-red-500 fill-current" />
          <span>by</span>
          <a
            href="https://github.com/ordinall"
            target="_blank"
            rel="noopener noreferrer"
            className="font-semibold hover:underline"
          >
            ordinall
          </a>
        </span>
        <button
          className="text-gray-500 dark:text-gray-300 transition-colors duration-300"
          onClick={() => setDarkMode(!darkMode)}
          aria-label="Toggle Dark Mode"
        >
          {darkMode ? <Sun className="h-6 w-6" /> : <Moon className="h-6 w-6" />}
        </button>
      </header>

      <div className="flex-grow flex flex-col items-center justify-start w-full">
        <div className="flex flex-col items-center justify-center w-full max-w-6xl">
          <h1 className="text-4xl md:text-5xl font-bold text-gray-800 dark:text-gray-100 mb-8 mt-8 text-center transition-all duration-300 ease-in-out hover:text-gray-700 dark:hover:text-gray-300">
            Wallpaper Engine Reverse Image Search
          </h1>
          <form onSubmit={handleSubmit} className="w-full max-w-md">
            <div className="mb-4 flex items-center">
              <input
                type="text"
                value={inputValue}
                onChange={handleInputChange}
                placeholder="Enter image URL or upload/paste an image"
                className={`w-full px-4 py-2 text-gray-700 dark:text-gray-200 bg-white dark:bg-gray-800 border dark:border-gray-700 border-gray-300 rounded-l-lg focus:outline-2 focus:outline-blue-500 ${validationError === 1 ? 'ring-red-500 ring-2' : ''} transition-all duration-300 ease-in-out disabled:bg-gray-200 dark:disabled:bg-gray-900`}
                disabled={searching || !isHealthy || checkingHealth}
                onPasteCapture={handlePasteCapture}
                onFocus={handleOnFocus}
              />
              <label htmlFor="file-upload">
                <div className={`px-4 py-2 border-r border-t border-b border-gray-300 dark:border-gray-700 rounded-r-lg cursor-pointer ${validationError === 1 ? 'ring-red-500 ring-2' : ''} transition-all duration-300 ease-in-out ${(searching || !isHealthy || checkingHealth) ? 'dark:bg-gray-900 bg-gray-200' : 'bg-white dark:bg-gray-800'}`}>
                  <div className="right-2 top-1/2 transform">
                    <Upload className="h-6 w-6 text-gray-400 hover:text-gray-600 dark:text-gray-300 dark:hover:text-gray-100 transition-colors duration-300" />
                  </div>
                </div>
              </label>
              
              <input
                id="file-upload"
                type="file"
                onChange={handleFileChange}
                className="hidden"
                accept="image/*"
                disabled={searching || !isHealthy || checkingHealth}
              />
            </div>
            <div className="flex items-center mb-4">
              <input
                type="checkbox"
                id="remove-nsfw"
                checked={removeNsfw}
                onChange={(e) => {
                  setRemoveNsfw(e.target.checked)
                  localStorage.setItem('removeNsfw', e.target.checked ? '1' : '0')
                }}
                className="mr-2"
              />
              <label htmlFor="remove-nsfw" className="text-sm text-gray-600 dark:text-gray-300">
                Remove NSFW content
              </label>
            </div>
            <button
              type="submit"
              className="w-full px-4 py-2 bg-blue-500 dark:bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-600 dark:hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50 transition-all duration-300 ease-in-out disabled:opacity-50"
              disabled={searching || !isHealthy || checkingHealth}
            >
              {searching ? (
                  <div className="flex items-center justify-center">
                    <svg aria-hidden="true" className="inline w-6 h-6 text-blue-500 animate-spin fill-white" viewBox="0 0 100 101" fill="none" xmlns="http://www.w3.org/2000/svg">
                      <path d="M100 50.5908C100 78.2051 77.6142 100.591 50 100.591C22.3858 100.591 0 78.2051 0 50.5908C0 22.9766 22.3858 0.59082 50 0.59082C77.6142 0.59082 100 22.9766 100 50.5908ZM9.08144 50.5908C9.08144 73.1895 27.4013 91.5094 50 91.5094C72.5987 91.5094 90.9186 73.1895 90.9186 50.5908C90.9186 27.9921 72.5987 9.67226 50 9.67226C27.4013 9.67226 9.08144 27.9921 9.08144 50.5908Z" fill="currentColor"/>
                      <path d="M93.9676 39.0409C96.393 38.4038 97.8624 35.9116 97.0079 33.5539C95.2932 28.8227 92.871 24.3692 89.8167 20.348C85.8452 15.1192 80.8826 10.7238 75.2124 7.41289C69.5422 4.10194 63.2754 1.94025 56.7698 1.05124C51.7666 0.367541 46.6976 0.446843 41.7345 1.27873C39.2613 1.69328 37.813 4.19778 38.4501 6.62326C39.0873 9.04874 41.5694 10.4717 44.0505 10.1071C47.8511 9.54855 51.7191 9.52689 55.5402 10.0491C60.8642 10.7766 65.9928 12.5457 70.6331 15.2552C75.2735 17.9648 79.3347 21.5619 82.5849 25.841C84.9175 28.9121 86.7997 32.2913 88.1811 35.8758C89.083 38.2158 91.5421 39.6781 93.9676 39.0409Z" fill="currentFill"/>
                    </svg>
                    <div className='w-2'></div>
                    Crunching Numbers...
                  </div>
                ) : (
                  'Search'
              )}
            </button>
          </form>
        </div>
        <div className='flex justify-center items-center mt-3'>
          {
            checkingHealth ? (
              <p className="text-center text-gray-600 dark:text-gray-300">
                Checking server health...
              </p>
            ) : (!isHealthy ? (
              <>
                <span className="relative flex h-3 w-3">
                  <span className="relative inline-flex rounded-full h-3 w-3 bg-red-500"></span>
                </span>
                <div className='w-2'></div>
                <p className="text-center text-gray-600 dark:text-gray-300">
                  Server is down, please try again later
                </p>
              </>

            ) : (
                <>
                  <span className="relative flex h-3 w-3">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                  </span>
                  <div className='w-2'></div>
                  <p className="text-center text-gray-600 dark:text-gray-300">
                    Server is up and ready to search
                  </p>
                </>
            ))
          }
        </div>
        <div className='flex justify-center items-center mt-4'>
          {
            datasetUpdated && (
              <p className="text-center text-gray-600 dark:text-gray-300">
                Dataset last updated on {new Intl.DateTimeFormat('en', { day: '2-digit' }).format(datasetUpdated)} {new Intl.DateTimeFormat('en', { month: 'short' }).format(datasetUpdated)} {new Intl.DateTimeFormat('en', { year: 'numeric' }).format(datasetUpdated)}
              </p>
            )
          }
        </div>
        <div className='flex justify-center items-center'>
          {
            searches && (
              <p className="text-center text-gray-600 dark:text-gray-300">
                {searches.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",")} searches made so far
              </p>
            )
          }
        </div>
        {searchError ? (
          <p className="text-center text-red-500 dark:text-red-400 mt-4">
            {searchErrorText !== '' ? 'An error occurred: ' + searchErrorText : 'An error occurred while searching, please try again later'}
          </p>
        ) : searchResponse && (
          <div className="mt-8 w-full max-w-6xl">
            <p className="text-center text-gray-400 mb-4">
              {searchResponse.total_documents.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",")} images searched in {searchResponse.processing_time.toFixed(2)} seconds
            </p>
            {
              resultEmpty && (
                <p className="text-center font-semibold mb-4">
                  No results found
                </p>
              )
            }
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
              {searchResponse.results.map((result) => (
                <div
                  key={result.fileid}
                  className="bg-white dark:bg-gray-800 rounded-lg shadow-md overflow-hidden transition-transform duration-300 cursor-pointer"
                  onClick={() => window.open(`https://steamcommunity.com/sharedfiles/filedetails/?id=${result.fileid}`)}
                >
                  <LazyLoadImage
                    src={result.url}
                    alt="Wallpaper preview"
                    effect="opacity"
                    width={"100%"}
                    style={{
                      width: '100%',
                      aspectRatio: '1/1',
                      objectFit: 'cover'
                    }}
                    
                  />
                  {/* <img src={result.url} alt="Wallpaper preview" className="w-full aspect-square object-cover" /> */}
                  <div className="p-4">
                    <h3 className="font-semibold text-gray-800 dark:text-gray-200 truncate">{result.title}</h3>
                    <p className="text-sm text-gray-400 mb-1">Similarity: {result.score.toFixed(2)}%</p>
                    <div className="mb-2 flex items-start space-x-1">
                      <button 
                        className="text-xs bg-white dark:bg-gray-800 dark:hover:bg-gray-700 hover:bg-gray-100 text-gray border border-gray-400 py-1 px-2 rounded-lg shadow inline-flex items-center space-x-1"
                        onClick={(e) => {
                          window.location.href = `steam://openurl/https://steamcommunity.com/sharedfiles/filedetails/?id=${result.fileid}`
                          e.stopPropagation();
                        }}
                      >
                          <SteamLogo className="h-5 w-5" />
                          <span>
                            Open in Steam
                          </span>
                      </button>
                      <SearchThisButton onClick={() => searchImage(result.url)} enabled={!searching} />
                    </div>
                    <div className="flex flex-wrap gap-1 mb-2">
                      {result.tags.map((tag, index) => (
                        <span key={index} className="px-2 py-1 bg-gray-200 text-gray-700 dark:bg-gray-700 dark:text-gray-200 text-xs rounded-full">
                          {tag}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
      <div className='pt-100'></div>
      {/* <footer className="mt-8 text-center text-gray-500 flex items-center justify-center space-x-1 transition-all duration-300 ease-in-out hover:text-gray-700" style={{position: 'sticky', bottom: 0}}>  
        <span>Made with</span>
        <Heart className="h-4 w-4 text-red-500 fill-current" />
        <span>by</span>
        <a href="https://github.com/ordinall" target="_blank" rel="noopener noreferrer" className="font-semibold hover:underline">
          ordinall
        </a>
      </footer> */}
      
    </div>
  )
}